/* 
  URL: https://api.com/users/99/orders/55

  We are looking for User #99, and specifically their Order #55.
*/

// Backend Example (Express.js)
// We define the route using colons to create variables
app.get('/api/users/:userId/orders/:orderId', (req, res) => {

  // The framework extracts them into the req.params object
  const userId = req.params.userId;   // "99"
  const orderId = req.params.orderId; // "55"

  const order = db.getOrder(userId, orderId);
  res.json(order);
});
